const isNode = typeof process !== 'undefined' && process.versions && process.versions.node;
const port = isNode ? require('worker_threads').parentPort : self;
const listen = (fn) => { if (isNode) port.on('message', fn); else self.onmessage = (e) => fn(e.data) };
const send = (m) => port.postMessage(m);
const pending = new Map();
let seq = 0;
listen((m) => {
  if (m && m.type === 'api-res') {
    const p = pending.get(m.seq);
    if (p) { pending.delete(m.seq); m.ok ? p.resolve({ value: m.value, warning: m.warning }) : p.reject(new Error(m.value)) }
  } else if (m && m.type === 'run') {
    exec(m.snippet)
  }
});
const call = (op, args) => new Promise((resolve, reject) => {
  const id = ++seq
  pending.set(id, { resolve, reject })
  send({ type: 'api-req', seq: id, op, args })
});
const api = {
  getObject: (id) => call('getObject', [id]).then((r) => r.value),
  setProp: (id, prop, value) => call('setProp', [id, prop, value]).then((r) => r.value),
  getVar: (name) => call('getVar', [name]).then((r) => r.value),
  setVar: (name, expr) => call('setVar', [name, expr]).then((r) => r.value),
  findObject: async (name) => { // مساعد موثق الهشاشة: التحذير يُرجَع مع النتيجة
    const r = await call('findObject', [name])
    return { object: r.value, warning: r.warning }
  },
}
async function exec(snippet) {
  try {
    const fn = new Function('api', '"use strict"; return (async () => {\n' + snippet + '\n})()')
    const value = await fn(api)
    send({ type: 'done', ok: true, value: value === undefined ? null : value })
  } catch (e) {
    send({ type: 'done', ok: false, value: String(e && e.message || e) })
  }
}
